<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('clinical.view');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$id=(int)($_GET['id']??$_POST['id']??0);$st=db()->prepare("SELECT r.*,p.name patient_name,p.primary_professional_id,u.name professional_name FROM clinical_records r JOIN patients p ON p.id=r.patient_id AND p.tenant_id=r.tenant_id JOIN users u ON u.id=r.professional_id AND u.tenant_id=r.tenant_id WHERE r.id=:id AND r.tenant_id=:t");$st->execute(['id'=>$id,'t'=>$user['tenant_id']]);$r=$st->fetch();if(!$r||!\App\Core\Rbac::canViewPatientClinical($user,$r)){http_response_code(403);require APP_ROOT.'/app/views/403.php';exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='approve'&&\App\Core\Rbac::allows((int)$user['id'],'clinical.approve')&&(int)$r['supervisor_id']===(int)$user['id']&&$r['status']==='pending_approval'){db()->prepare("UPDATE clinical_records SET status='signed',approved_by=:u,signed_at=NOW(),updated_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['u'=>$user['id'],'id'=>$id,'t'=>$user['tenant_id']]);audit('clinical.record_cosign','clinical_record',$id,[]);flash('success','Registro revisado e coassinado pelo supervisor.');redirect('clinical/view.php?id='.$id);}if($action==='sign'&&(int)$r['professional_id']===(int)$user['id']&&$user['role_slug']!=='supervised'&&in_array($r['status'],['draft','approved'],true)){db()->prepare("UPDATE clinical_records SET status='signed',signed_at=NOW(),updated_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['id'=>$id,'t'=>$user['tenant_id']]);audit('clinical.record_sign','clinical_record',$id,[]);flash('success','Registro assinado e bloqueado para edição nesta versão.');redirect('clinical/view.php?id='.$id);}}$content=\App\Core\Crypto::decrypt($r['content_enc'],true);audit('clinical.record_view','clinical_record',$id,[]);layout('Registro clínico',function()use($r,$content,$user){?><div class="page-head"><div><span class="eyebrow"><?=e(strtoupper($r['record_type']))?> · <?=e(date('d/m/Y H:i',strtotime($r['created_at'])))?></span><h1 data-private><?=e($r['patient_name'])?></h1><p>Profissional: <?=e($r['professional_name'])?> · <span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></p></div><div class="split-actions"><a class="button ghost" href="<?=e(url('patients/view.php?id='.$r['patient_id']))?>">Paciente</a><?php if((int)$r['professional_id']===(int)$user['id']&&$user['role_slug']!=='supervised'&&in_array($r['status'],['draft','approved'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button" name="action" value="sign">Assinar registro</button></form><?php endif?><?php if($r['status']==='pending_approval'&&(int)$r['supervisor_id']===(int)$user['id']&&\App\Core\Rbac::allows((int)$user['id'],'clinical.approve')):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button" name="action" value="approve">Revisar e coassinar</button></form><?php endif?></div></div><section class="card"><?php if($r['record_type']==='soap'):?><div class="soap-grid"><?php foreach(['S'=>'Subjetivo','O'=>'Objetivo','A'=>'Avaliação','P'=>'Plano'] as $k=>$label):?><article class="soap-box"><strong><?=$k?> · <?=$label?></strong><p data-private><?=nl2br(e($content[$k]??''))?></p></article><?php endforeach?></div><?php else:?><?php foreach($content as $k=>$v):?><article class="record" style="margin-bottom:12px"><strong><?=e(ucfirst(str_replace('_',' ',$k)))?></strong><p data-private><?=nl2br(e($v))?></p></article><?php endforeach?><?php endif?><p class="help">Registros assinados devem ser tratados como imutáveis. Correções posteriores devem gerar novo registro complementar.</p></section><?php },['active'=>'clinical']);
